const { ExprError } = require('./errors');

function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '**':
      // C pow (used by Python floats): 1 ** y and (-1) ** ±inf are 1.
      if (left === 1 || (left === -1 && (right === Infinity || right === -Infinity))) return 1;
      return left ** right;
    case '//': {
      // Python's float floor division, exact for integral inputs.
      let remainder = left % right;
      let quotient = (left - remainder) / right;
      if (remainder !== 0 && (right < 0) !== (remainder < 0)) quotient -= 1;
      if (quotient === 0) return 0;
      const floored = Math.floor(quotient);
      return quotient - floored > 0.5 ? floored + 1 : floored;
    }
    case '%': {
      // Python's float modulo: the result takes the divisor's sign.
      const remainder = left % right;
      if (remainder === 0) return 0;
      if ((right < 0) !== (remainder < 0)) return remainder + right;
      return remainder;
    }
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

