'use strict';

const { ExprError } = require('./errors');

const PAIRS = new Set(['**', '//', '<=', '>=', '==', '!=']);
const SINGLES = new Set(['+', '-', '*', '/', '%', '<', '>', '(', ')', ',']);

/** Convert source to positioned tokens without repeatedly slicing its suffix. */
function tokenize(source) {
  const tokens = [];
  const whitespace = /\s+/y;
  const number = /(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?/y;
  const identifier = /[A-Za-z_][A-Za-z0-9_]*/y;
  let offset = 0;
  while (offset < source.length) {
    whitespace.lastIndex = offset;
    if (whitespace.test(source)) offset = whitespace.lastIndex;
    if (offset === source.length) break;
    const column = offset + 1;
    number.lastIndex = offset;
    const numeric = number.exec(source);
    if (numeric) {
      tokens.push({ type: 'number', value: Number(numeric[0]), column });
      offset = number.lastIndex;
      continue;
    }
    identifier.lastIndex = offset;
    const name = identifier.exec(source);
    if (name) {
      tokens.push({ type: 'identifier', value: name[0], column });
      offset = identifier.lastIndex;
      continue;
    }
    const pair = source.slice(offset, offset + 2);
    if (PAIRS.has(pair)) {
      tokens.push({ type: 'operator', value: pair, column });
      offset += 2;
    } else if (SINGLES.has(source[offset])) {
      tokens.push({ type: 'operator', value: source[offset], column });
      offset += 1;
    } else {
      throw new ExprError('Unexpected character', column);
    }
  }
  tokens.push({ type: 'eof', value: '', column: source.length + 1 });
  return tokens;
}

module.exports = { tokenize };

'use strict';

const { ExprError } = require('./errors');

const COMPARISONS = new Set(['<', '<=', '>', '>=', '==', '!=']);
const PRODUCTS = new Set(['*', '/', '//', '%']);
const FUNCTIONS = new Set(['min', 'max', 'abs']);

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const isOperator = value => current().type === 'operator' && current().value === value;
  const expect = value => {
    if (!isOperator(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  /** Chained comparisons form one flat node: a < b <= c means a < b and b <= c. */
  function comparison() {
    const first = sum();
    if (current().type !== 'operator' || !COMPARISONS.has(current().value)) return first;
    const operands = [first];
    const operators = [];
    while (current().type === 'operator' && COMPARISONS.has(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (isOperator('+') || isOperator('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (current().type === 'operator' && PRODUCTS.has(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  /** Signs are collected iteratively so long sign runs do not recurse. */
  function unary() {
    const signs = [];
    while (isOperator('+') || isOperator('-')) signs.push(take());
    let operand = power();
    for (let index = signs.length - 1; index >= 0; index -= 1) {
      operand = { type: 'unary', operator: signs[index], operand };
    }
    return operand;
  }

  /** ** binds tighter than a sign on its left and is right-associative. */
  function power() {
    const base = primary();
    if (!isOperator('**')) return base;
    const operator = take();
    return binary(operator, base, unary());
  }

  function call(name) {
    if (!FUNCTIONS.has(name.value)) throw new ExprError('Unknown function', name.column);
    take();
    if (isOperator(')')) throw new ExprError('Wrong argument count', name.column);
    const args = [comparison()];
    while (isOperator(',')) {
      if (name.value === 'abs') throw new ExprError('Wrong argument count', name.column);
      take();
      args.push(comparison());
    }
    expect(')');
    return { type: 'call', name: name.value, args };
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (isOperator('(')) return call(token);
      return { type: 'variable', name: token.value, column: token.column };
    }
    if (token.type === 'operator' && token.value === '(') {
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
  return expression;
}

module.exports = { parse };

