assert.ok(Object.is(evaluate('-1 // 3 * 0 + 0 // -5'), 0)); assert.ok(Object.is(evaluate('0 % -5'), 0));
eq('1 < 2 < 3', true); eq('3 > 2 > 1', true); eq('1 < 3 < 2', false); eq('(1 < 2) < 3', true);
eq('(1 < 2) + (2 < 3)', 2); eq('(1 < 2) == 1', true); eq('1 == 1.0 != 2', true);
eq('min(3, 1, 2)', 1); eq('max(1, 5, 2)', 5); eq('abs(-3)', 3); eq('1.5e-3 * 1000', 1.5); eq('.5 + 5.', 5.5);
eq('5 - 3 - 1', 1); eq('100 / 10 / 5', 2); eq('- - 3', 3); eq('1 ** 1e400', 1);
let reads = []; const v = { get a() { reads.push('a'); return 1; }, get b() { reads.push('b'); return 0; }, get c() { reads.push('c'); return 5; } };
eq('a < b < c', false, v); assert.deepEqual(reads, ['a', 'b']);
reads = []; eq('b < a < c', true, v); assert.deepEqual(reads, ['b', 'a', 'c']);
eq('2 > 1 > nope', false, { nope: undefined }); eq('1 > 2 < nope', false);
assert.equal(col('1 +  x'), 6); assert.equal(col('1 / 0'), 3); assert.equal(col('1 +   0 //  0'), 9);
assert.equal(col('1 + '), 5); assert.equal(col('  foo(1)'), 3); assert.equal(col('abs(1, 2)'), 1); assert.equal(col(' min()'), 2);
assert.equal(col('min(1,)'), 7); assert.equal(col('1 2'), 3); assert.equal(col('1 $'), 3); assert.equal(col('foo(1 +)'), 1);
assert.equal(col('2 > 3 > 1 / 0'), 'no error'); assert.equal(col('1 < 2 < (3'), 11);
const n = 200000;
let t = Date.now(); const long = Array.from({ length: n }, (_, i) => String(i % 7 + 1)).join(' + ');
eq(long, Array.from({ length: n }, (_, i) => i % 7 + 1).reduce((a, b) => a + b));
const chain = Array.from({ length: n }, (_, i) => String(i)).join(' < '); eq(chain, true);
eq('-'.repeat(n) + '1', 1); eq(Array(n).fill('2').join(' * 1 // '), 2);
console.log('ok', Date.now() - t, 'ms');

